// Exact finite material with one full physical input guard.
// Lossless runtime compression preserves every selected field and coordinate.
export const starcatcherSupplementalInstallationData=await(async()=>{
 if(!globalThis.JSZip)await import('./vendor/jszip.min.js');
 const archive=await globalThis.JSZip.loadAsync("",{base64:true,checkCRC32:true});
 return JSON.parse(await archive.file('installation.json').async('string'));
})();
